{
  "research_concepts": [
    "opponent next-possession points per possession",
    "play-type labeling",
    "AVOID labels",
    "own-sequence lags",
    "defensive transition after offensive play type",
    "NBA play-by-play data quality"
  ],
  "methodological_questions": [
    "How to define and extract reliable opponent next-possession PPP",
    "How to avoid lookahead/leakage bias when inferring play types from PBP",
    "How to handle possession breaks, substitutions, end-of-period filtering",
    "Confounders: score margin, time remaining, opponent and own lineup quality",
    "Minimum sample size to detect small (~0.02 PPP) effects by play type",
    "Threat of systematic labeling artifacts (assisted-flag leak, foul leakage)",
    "How to model own-sequence lags without introducing autocorrelation biases",
    "Threshold at which a downstream effect would change an AVOID label"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-APPS-075",
      "status_as_recorded": "not a hypothesis test",
      "finding": "4/8 play types show a downstream (opponent next-possession) effect: CUT adds 0.0220, TRANSITION 0.0145, SPOT_UP 0.0124, POST_UP 0.0194 to Extended Possession Value. DRIVE downstream not real (opp ATT +0.0024). Player downstream mostly non-significant except M. M."
    },
    {
      "id": "FAM:SF-APPM-014",
      "status_as_recorded": "tool_eval_fail",
      "finding": "Play-type label accuracy/distribution audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail."
    },
    {
      "id": "FAM:SF-PAP-096",
      "status_as_recorded": "artifact",
      "finding": "SPOT_UP 2.83 PPP (100% makes) because assisted flag exists only on makes; after rewrite, SPOT_UP ~1.16, TRANSITION ~1.20."
    },
    {
      "id": "FAM:SF-CHT-025",
      "status_as_recorded": "artifact",
      "finding": "OTHER PPP inflated by 36% foul endings; DRIVE 12pp below foul benchmark; initiation_type maps only 0.7% of possessions."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-APPM-014",
      "what_failed": "play-type label accuracy/distribution audit",
      "why": "Systematic labeling errors: OTHER over-inclusion, low-confidence labels, foul possessions leaking into OTHER, PPP inflation, MIA identity mismatch."
    },
    {
      "id": "FAM:SF-PAP-096",
      "what_failed": "possession-level play-type PPP estimates using initial classifier",
      "why": "Assisted-field artifact: flag only on made baskets created 100% makes for SPOT_UP."
    },
    {
      "id": "FAM:SF-CHT-025",
      "what_failed": "play-type PPP analysis without foul diagnostics",
      "why": "Foul-leakage artifact: OTHER ending in fouls inflated PPP; DRIVE foul-draw undercounted."
    }
  ],
  "evidence_establishes": [
    "Opponent next-possession PPP after certain play types (CUT, TRANSITION, SPOT_UP, POST_UP) differs from baseline by ~0.01-0.02 PPP (SF-APPS-075).",
    "The inferred play-type labels from PBP contain serious systematic errors that distort PPP estimates and can create spurious sequence effects (SF-APPM-014, SF-PAP-096, SF-CHT-025)."
  ],
  "evidence_does_not_establish": [
    "Whether these small downstream effects ever exceed the threshold that would meaningfully change an AVOID label assignment.",
    "Whether own-sequence lags (previous own play type) produce any reliable effect.",
    "Whether the current play-type graph database has been cleansed of the known assisted-flag and foul-leakage artifacts.",
    "The statistical significance or multiplicity-corrected confidence of the PT-level suppression effects in SF-APPS-075."
  ],
  "own_inferences": [
    "The observed downstream effects (~0.02 PPP) are an order of magnitude smaller than direct BEST vs AVOID PPP gaps (≥0.4 PPP at team/player level), so they are unlikely to flip an AVOID label in practice.",
    "Undetected labeling leaks would introduce correlated errors between the play type of a possession and the apparent opponent next-possession PPP, making any small effect highly suspect.",
    "Even if own-sequence lags exist, they would be subject to the same labeling confounders and small signal-to-noise problems."
  ],
  "uncertainties": [
    "The exact metric and threshold used to assign AVOID labels in the engine are not specified, so 'large enough' is undefined.",
    "Own-sequence lags are not operationally defined (lag-1 play type, lag-1 outcome, etc.), and the appropriate handling of substitutions/breaks is unclear.",
    "It is unknown whether the graph database has been patched for the assisted-flag and foul-leakage bugs before being made available for this project."
  ],
  "historical_effect": {
    "changed_decision": "yes",
    "explanation": "The historical evidence shows that the opponent next-possession effects are so small (~0.01-0.02 PPP) that they are unlikely to ever be large enough to drive AVOID labels, and that the play-type labels themselves are contaminated by known artifacts that would invalidate any sensitive test. Without this evidence, one might have proceeded with a large-sample analysis unaware of these extreme labeling risks and the disappointing effect sizes."
  },
  "testability": {
    "p_testable": 0.35,
    "blocking_constraints": [
      {
        "code": "LABEL_ERROR",
        "text": "Play-type labels from PBP are known to contain systematic errors (OTHER over-inclusion, foul leakage, assisted-flag bugs) that directly affect the possessions used to compute opponent next-possession PPP and own-sequence lags."
      },
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Expected effect sizes (~0.02 PPP) are very small, requiring tens of thousands of possessions per play type to achieve adequate statistical power after multiplicity correction; sparse play types may never have sufficient sample."
      },
      {
        "code": "LEAKAGE_LOOKAHEAD",
        "text": "If any label component (e.g., assisted flag) depends on future outcomes, the play-type classification of a possession can leak information about the subsequent opponent possession, creating a mechanical correlation."
      }
    ]
  },
  "prior_work": {
    "already_answered": "partly",
    "cited": [
      "FAM:SF-APPS-075",
      "FAM:SF-APPM-014"
    ],
    "summary": "SF-APPS-075 measured opponent next-possession suppression for eight play types and found it statistically detectable but practically tiny (0.01-0.02 PPP). SF-APPM-014 documented widespread misclassification and PPP inflation in the play-type labels derived from the NBA PBP feed. Together they show that the question is partly answered (effects exist but are small) and that unaddressed label errors make any confirmatory analysis high-risk."
  },
  "risks": [
    {
      "code": "LABEL_ERROR",
      "text": "Unknown whether the play-type graph database has been repaired for the assisted-flag, foul-leakage, and OTHER-overclassification problems; any sequence analysis will inherit those biases."
    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Smallest effect of interest (~0.03-0.05 PPP to be 'large enough') may be undetectable for many play types even with four seasons of data, particularly for own-sequence lags where sample multiplies by PT-bin combinations."
    },
    {
      "code": "LEAKAGE_LOOKAHEAD",
      "text": "Any remaining lookahead in play-type inference (e.g., using the assisted flag) could artificially constrain opponent next-possession outcomes."
    },
    {
      "code": "CONFOUNDING",
      "text": "Opponent next-possession PPP is strongly confounded by game state (score margin, period, time remaining), opponent offensive quality, and own lineup defensive quality; failure to control these would produce spurious play-type differences."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Testing 8+ play types for downstream effects and many more lag structures multiplies the false-positive risk."
    }
  ],
  "predicted_outcome": {
    "supported": 0.10,
    "rejected": 0.55,
    "untestable": 0.15,
    "artifact": 0.15,
    "uncertain": 0.05
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "For each play type X, the average difference between opponent next-possession PPP (points allowed per opponent possession following the end of a possession labelled X) and the global average opponent PPP. For own-sequence lags, the average difference in current-possession PPP when the previous own possession was of play type Y, compared to baseline. 'Large enough' is defined as a suppression ≥ 0.03 PPP (approx. 2.5 points per 100 possessions) that survives Bonferroni correction.",
    "unit": "One offensive possession (and the immediately following opponent possession for downstream; the current possession and the immediately preceding own possession for lags).",
    "sample": "All possessions from 2022-23 through 2025-26 regular season and playoffs in the graph database, excluding possessions that end with technical free throws, end-of-quarter/half, or those where the next possession cannot be assigned because of substitutions/timeouts/garbage time (< 5 min in 4th quarter, score differential >20). Own-sequence lags further require that the two consecutive possessions belong to the same stint (no subs) and that neither is a residual possession after a made technical free throw.",
    "power": "Simulate using observed possession counts per play type from SF-APPS-075 (if available). With ~10,000 DRIVE possessions and an anticipated effect of 0.02 PPP, 80% power at α=0.05/10 requires ~25,000 possessions; pooling seasons may approach this for common play types but not for rarer ones. For own lags, double the per-cell requirement due to sparser combinations.",
    "controls": "Linear mixed model with fixed effects for play type (X for downstream, Y for lag), score margin (±10 point bins), period, time remaining (categorical), opponent team (random intercept), and team defense APM quintile.",
    "falsification": "1) Replicate the assisted-flag and foul-leakage artifacts on the current dataset to ensure they are absent. 2) Test whether previous-possession direct PPP (not play type) predicts current PPP to check if any observed lag effect is specific to play type. 3) Test whether randomly permuting play-type labels across possessions eliminates the estimated downstream effects.",
    "multiplicity": "Bonferroni correction over the number of play types tested (n ≈ 8 downstream, n≈8 own-lag). Report both corrected and uncorrected p-values.",
    "decision_rule": "A play type’s downstream or own-lag effect is declared 'large enough to drive AVOID labels' only if (a) the estimated suppression is ≥ 0.03 PPP, (b) the null hypothesis of zero effect is rejected at the Bonferroni-corrected 5% level, and (c) all falsification tests pass.",
    "data_version": "NBA play-by-play and matchup data from 2022-23 through 2025-26, processed through the play-type graph database as of 2026-06-19, after manual verification that the assisted-flag and foul-leakage bugs have been fixed."
  }
}

